Section Head.
  Variables (ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
            (F : bvmap 5 word) (fc : bv 32) (m : mem).
  Variables (lo c CA p cnt mc : Z).
  Let P := CA + PCLASS_SIZE * c.
  Hypothesis MI : ltac2:(zQ "20!hpe!kjb@2$1$0?1m").
  Hypothesis ST : ltac2:(zQ "40!h9!hpe!im5!igc@4$2$1?1m?2lo@2$3@1$0#k0?2sp").
  Hypothesis LO : ltac2:(zQ "20!kt9!ku1@2$1@1$0?5HCEIL?2lo").  Hypothesis HI : ltac2:(zQ "40!h9!hke!ku1!igc@2$2@2$1?2lo+n0@2$3@1$0#k0?2sp").
  Hypothesis Ha0 : ltac2:(zQ "40!ivb!h9!iue!jc@3$0@1$3@1$1#k0?2a0@1$2?2CA"). Hypothesis Ha1 : ltac2:(zQ "50!ivb!h9!krb!iue!jc@3$0@1$4@1$1#k0?2a1@1$3$2"). Hypothesis Ha2 : ltac2:(zQ "40!ivb!h9!iue!jc@3$0@1$3@1$1#k0?2a2@1$2?1c"). Hypothesis Ha3 : ltac2:(zQ "40!ivb!h9!iue!jc@3$0@1$3@1$1#k0?2a3@1$2?1p").
